PTX_SOURCE = r"""
.version 7.0
.target sm_80
.address_size 64

.visible .entry batched_gemm_fp16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 batch,
    .param .u32 m,
    .param .u32 k,
    .param .u32 n
)
{
    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    .reg .u64 %A, %B, %C;
    .reg .u32 %batch, %m, %k, %n;
    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];
    ld.param.u32 %batch, [batch];
    ld.param.u32 %m, [m];
    ld.param.u32 %k, [k];
    ld.param.u32 %n, [n];

    // -------------------------------------------------
    // Compute global thread index (1‑D)
    // -------------------------------------------------
    .reg .u32 %tid, %blockId, %global_idx32;
    .reg .u64 %global_idx;
    mov.u32 %tid, %tid.x;
    mov.u32 %blockId, %ctaid.x;
    mad.lo.u32 %global_idx32, %blockId, %ntid.x, %tid;   // blockId * blockDim.x + tid
    cvt.u64.u32 %global_idx, %global_idx32;

    // -------------------------------------------------
    // Bounds check: total = batch * m * n
    // -------------------------------------------------
    .reg .u64 %total, %mn;
    mul.lo.u64 %mn, %m, %n;          // m * n
    mul.lo.u64 %total, %batch, %mn; // batch * m * n
    setp.ge.u64 %p_out_of_range, %global_idx, %total;
    @%p_out_of_range ret;

    // -------------------------------------------------
    // Decompose global index into (b, i, j)
    // -------------------------------------------------
    .reg .u64 %b, %ij, %i, %j, %tmp;
    div.u64 %b, %global_idx, %mn;                 // b = idx / (m*n)
    mul.lo.u64 %tmp, %b, %mn;
    sub.u64 %ij, %global_idx, %tmp;               // remainder = i*n + j
    div.u64 %i, %ij, %n;                          // i = remainder / n
    mul.lo.u64 %tmp, %i, %n;
    sub.u64 %j, %ij, %tmp;                        // j = remainder % n

    // -------------------------------------------------
    // Compute base pointers for this batch / row / column
    // -------------------------------------------------
    // A: address of A[b, i, 0]
    .reg .u64 %rowA;
    mad.lo.u64 %rowA, %b, %m, %i;                 // b*m + i
    mul.lo.u64 %rowA, %rowA, %k;                  // (b*m + i) * k
    mul.lo.u64 %rowA, %rowA, 2;                   // byte offset (half = 2 bytes)
    add.u64 %rowA, %A, %rowA;                     // pointer to start of row

    // B: address of B[b, 0, 0]
    .reg .u64 %batchB;
    mad.lo.u64 %batchB, %b, %k, 0;                // b*k
    mul.lo.u64 %batchB, %batchB, %n;              // b*k*n
    mul.lo.u64 %batchB, %batchB, 2;               // byte offset
    add.u64 %B, %B, %batchB;                      // B now points to start of batch

    // C: address of C[b, i, j]
    .reg .u64 %rowC;
    mad.lo.u64 %rowC, %b, %m, %i;                 // b*m + i
    mul.lo.u64 %rowC, %rowC, %n;                  // (b*m + i) * n
    add.u64 %rowC, %rowC, %j;                     // + j
    mul.lo.u64 %rowC, %rowC, 2;                   // byte offset
    add.u64 %rowC, %C, %rowC;                     // final pointer for output

    // -------------------------------------------------
    // Accumulate dot product over k using fp32 accumulation
    // -------------------------------------------------
    .reg .f32 %sum;
    mov.f32 %sum, 0f0;

    .reg .u32 %kk;
    mov.u32 %kk, 0;

    .reg .u16 %a16, %b16, %c16;
    .reg .f32 %a32, %b32;

    .reg .u64 %ptrA, %ptrB;
LOOP_K:
    setp.ge.u32 %p_k_done, %kk, %k;
    @%p_k_done bra END_LOOP_K;

    // Load A[b,i,kk]
    mul.lo.u64 %ptrA, %kk, 2;          // kk * sizeof(half)
    add.u64 %ptrA, %rowA, %ptrA;
    ld.global.u16 %a16, [%ptrA];
    cvt.f32.f16 %a32, %a16;

    // Load B[b,kk,j]  -> offset = kk * n + j
    mul.lo.u64 %ptrB, %kk, %n;
    add.u64 %ptrB, %ptrB, %j;
    mul.lo.u64 %ptrB, %ptrB, 2;
    add.u64 %ptrB, %B, %ptrB;
    ld.global.u16 %b16, [%ptrB];
    cvt.f32.f16 %b32, %b16;

    // FMA
    fma.rn.f32 %sum, %a32, %b32, %sum;

    add.u32 %kk, %kk, 1;
    bra LOOP_K;
END_LOOP_K:

    // Store result (convert back to half)
    cvt.f16.f32 %c16, %sum;
    st.global.u16 [%rowC], %c16;

    ret;
}
"""

# ----------------------------------------------------------------------
# Python wrapper that loads the PTX and launches the kernel
# ----------------------------------------------------------------------
import torch
from ptx_harness import ptx_load, ptx_launch

class ModelNew(torch.nn.Module):
    def __init__(self):
        super().__init__()
        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        A: (batch, m, k) fp16 tensor on CUDA
        B: (batch, k, n) fp16 tensor on CUDA
        Returns C: (batch, m, n) fp16 tensor on CUDA
        """
