        assert A.dtype == torch.float16 and B.dtype == torch.float16
        batch, m, k = A.shape
        _, _, n = B.shape

        C = torch.empty(batch, m, n, dtype=torch.float16, device=A.device)

        # Kernel launch configuration
        total_elements = batch * m * n
        threads_per_block = 256
        blocks = (total_elements + threads_per_block - 1) // threads_per_block
        grid = (blocks, 1, 1)
        block = (threads_per_block, 1, 1)

        # Arguments: pointers and dimensions (as 64‑bit/32‑bit ints)
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            int(batch),
            int(m),
            int(k),
            int(n)
        ]

        # Launch the kernel
        ptx_launch(self.module, "batched_gemm_fp16", grid, block, args)

